# Let me try yet another approach: sorting by column, then row
# Perhaps pixels within same color and column are packed together in output

def test_column_compaction(grid):
    """For each (color, column), collect all pixels sorted by row, then place consecutively"""
    from collections import defaultdict
    out = [[0]*10 for _ in range(10)]
    pixels_by_col = defaultdict(list)

    for r in range(len(grid)):
        for c in range(len(grid[r])):
            if grid[r][c] != 0:
                pixels_by_col[c].append((r, grid[r][c]))

    # For each column in INPUT, pack its pixels into output column 0, then 1, etc.
    col_order = sorted(pixels_by_col.keys())

    output_col = 0
    for input_col in col_order:
        if output_col >= 10:
            break
        cols_in_col = sorted(pixels_by_col[input_col])
        for r, color in cols_in_col:
            if output_col < 10:
                row = output_col
                out[row][output_col] = color
                output_col += 1

    return out

